{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2175-02-27 19:15:00",
      "speaker": "Doctor",
      "text": "Hello, Mr. ___. I’m Dr. ___. You’re in the hospital because you had a fall earlier tonight. Do you remember what happened?"
    },
    {
      "turn_number": 2,
      "time": "2175-02-27 19:16:00",
      "speaker": "Patient",
      "text": "I… not really. I was drinking, and next thing I know, EMS was there. My chest hurts pretty bad."
    },
    {
      "turn_number": 3,
      "time": "2175-02-27 19:17:00",
      "speaker": "Doctor",
      "text": "Yes, we did some scans, and you have several broken ribs on the left side. Six of them, to be exact. That’s why your chest is painful."
    },
    {
      "turn_number": 4,
      "time": "2175-02-27 19:18:00",
      "speaker": "Patient",
      "text": "Six? Oh no… is anything else broken?"
    },
    {
      "turn_number": 5,
      "time": "2175-02-27 19:19:00",
      "speaker": "Doctor",
      "text": "We checked your head, neck, spine, and abdomen. No fractures or internal injuries. Your head CT was clear, which is good. But we did see a small pneumothorax—collapsed lung—at the top of your left lung. It’s tiny and stable, so we’re watching it, not treating it right now."
    },
    {
      "turn_number": 6,
      "time": "2175-02-27 19:20:00",
      "speaker": "Patient",
      "text": "That sounds scary. Could that get worse?"
    },
    {
      "turn_number": 7,
      "time": "2175-02-27 19:21:00",
      "speaker": "Doctor",
      "text": "We’re monitoring it closely. Most small ones like this heal on their own. We’ll do another chest X-ray tomorrow to check."
    },
    {
      "turn_number": 8,
      "time": "2175-02-27 19:22:00",
      "speaker": "Patient",
      "text": "Okay… I’ve been having a tough time lately. With the myeloma, the treatments, everything."
    },
    {
      "turn_number": 9,
      "time": "2175-02-27 19:23:00",
      "speaker": "Doctor",
      "text": "I see you’ve been through a lot. You’re on Revlimid and Velcade for your multiple myeloma, correct?"
    },
    {
      "turn_number": 10,
      "time": "2175-02-27 19:24:00",
      "speaker": "Patient",
      "text": "Yes. I had pneumonia a while back, so they paused Revlimid. Just restarted at a higher dose."
    },
    {
      "turn_number": 11,
      "time": "2175-02-27 19:25:00",
      "speaker": "Doctor",
      "text": "Got it. Your blood counts are low but stable—your platelets are at 51, which is lower than usual. Because of that and your INR being high when you came in, we’ve held your warfarin for now."
    },
    {
      "turn_number": 12,
      "time": "2175-02-27 19:26:00",
      "speaker": "Patient",
      "text": "Will I need it again?"
    },
    {
      "turn_number": 13,
      "time": "2175-02-27 19:27:00",
      "speaker": "Doctor",
      "text": "We’ll discuss that with your oncology team. For now, we’re focusing on healing your ribs and making sure you don’t get complications like pneumonia."
    },
    {
      "turn_number": 14,
      "time": "2175-02-27 19:28:00",
      "speaker": "Patient",
      "text": "I’ve had pneumonia before. I don’t want that again."
    },
    {
      "turn_number": 15,
      "time": "2175-02-27 19:29:00",
      "speaker": "Doctor",
      "text": "Exactly. That’s why we’re giving you an incentive spirometer. You need to use it every hour while awake to keep your lungs open."
    },
    {
      "turn_number": 16,
      "time": "2175-02-27 19:30:00",
      "speaker": "Patient",
      "text": "They showed me that earlier. I’ll do it."
    },
    {
      "turn_number": 17,
      "time": "2175-02-27 19:31:00",
      "speaker": "Doctor",
      "text": "Good. Also, your diabetes is stable. We’ve doubled your long-acting insulin to 60 units at bedtime because your levels were running high."
    },
    {
      "turn_number": 18,
      "time": "2175-02-27 19:32:00",
      "speaker": "Patient",
      "text": "I’ve been on insulin for years. Is that safe with the other meds?"
    },
    {
      "turn_number": 19,
      "time": "2175-02-27 19:33:00",
      "speaker": "Doctor",
      "text": "Yes, it’s safe. We’re monitoring your glucose closely. No lows so far."
    },
    {
      "turn_number": 20,
      "time": "2175-02-28 08:15:00",
      "speaker": "Doctor",
      "text": "Good morning. How are you feeling today?"
    },
    {
      "turn_number": 21,
      "time": "2175-02-28 08:16:00",
      "speaker": "Patient",
      "text": "Still hurting, and I felt nauseous last night. Threw up a little."
    },
    {
      "turn_number": 22,
      "time": "2175-02-28 08:17:00",
      "speaker": "Doctor",
      "text": "Yes, your belly was distended. We did an X-ray and saw your stomach was very full. We placed a small tube through your nose to help it drain—called an NG tube."
    },
    {
      "turn_number": 23,
      "time": "2175-02-28 08:18:00",
      "speaker": "Patient",
      "text": "That’s the tube I woke up with? It’s uncomfortable."
    },
    {
      "turn_number": 24,
      "time": "2175-02-28 08:19:00",
      "speaker": "Doctor",
      "text": "I know. But it helped empty your stomach. We removed it this morning, and you tolerated that well. We’ll start you on liquids and advance to solid food slowly."
    },
    {
      "turn_number": 25,
      "time": "2175-02-28 08:20:00",
      "speaker": "Patient",
      "text": "Can I have real food today?"
    },
    {
      "turn_number": 26,
      "time": "2175-02-28 08:21:00",
      "speaker": "Doctor",
      "text": "If you keep tolerating liquids, yes. But take it slow. Your body’s been through a lot."
    },
    {
      "turn_number": 27,
      "time": "2175-02-28 14:30:00",
      "speaker": "Doctor",
      "text": "The repeat chest X-ray shows the pneumothorax is gone. That’s great news."
    },
    {
      "turn_number": 28,
      "time": "2175-02-28 14:31:00",
      "speaker": "Patient",
      "text": "Really? That’s a relief."
    },
    {
      "turn_number": 29,
      "time": "2175-02-28 14:32:00",
      "speaker": "Doctor",
      "text": "Yes. Your pain is better too—we’ve switched you from the IV morphine pump to oral oxycodone as needed."
    },
    {
      "turn_number": 30,
      "time": "2175-02-28 14:33:00",
      "speaker": "Patient",
      "text": "It helps, but I get sleepy."
    },
    {
      "turn_number": 31,
      "time": "2175-02-28 14:34:00",
      "speaker": "Doctor",
      "text": "That’s common. Take it with food, and if it’s too strong, you can take half a pill and let us know. But don’t skip doses—deep breathing is harder when you’re in pain."
    },
    {
      "turn_number": 32,
      "time": "2175-03-01 09:00:00",
      "speaker": "Doctor",
      "text": "You’re doing well. You’re eating regular food, walking with the walker, and your labs are stable."
    },
    {
      "turn_number": 33,
      "time": "2175-03-01 09:01:00",
      "speaker": "Patient",
      "text": "So I can go home?"
    },
    {
      "turn_number": 34,
      "time": "2175-03-01 09:02:00",
      "speaker": "Doctor",
      "text": "Not quite yet. Because of your myeloma, low platelets, and recent fall, we’re sending you to a rehab facility for a few days—just to make sure you’re safe to go home."
    },
    {
      "turn_number": 35,
      "time": "2175-03-01 09:03:00",
      "speaker": "Patient",
      "text": "Rehab? I guess that makes sense. I’m still pretty weak."
    },
    {
      "turn_number": 36,
      "time": "2175-03-01 09:04:00",
      "speaker": "Doctor",
      "text": "Exactly. They’ll help you build strength and make sure you can manage at home. You’ll still use the walker for support."
    },
    {
      "turn_number": 37,
      "time": "2175-03-02 10:00:00",
      "speaker": "Doctor",
      "text": "Today’s the day. You’re being discharged to ___ Rehabilitation and Sub-Acute Care."
    },
    {
      "turn_number": 38,
      "time": "2175-03-02 10:01:00",
      "speaker": "Patient",
      "text": "Okay. What do I need to do when I get there?"
    },
    {
      "turn_number": 39,
      "time": "2175-03-02 10:02:00",
      "speaker": "Doctor",
      "text": "Keep using the incentive spirometer, take your pain meds as needed, and work with therapy. Watch for shortness of breath or increasing chest pain—go to the ER if that happens."
    },
    {
      "turn_number": 40,
      "time": "2175-03-02 10:03:00",
      "speaker": "Patient",
      "text": "And my meds?"
    },
    {
      "turn_number": 41,
      "time": "2175-03-02 10:04:00",
      "speaker": "Doctor",
      "text": "You’ll go home with oxycodone for pain, acetaminophen, your insulin, gabapentin, and your other usual meds. Warfarin will be re-evaluated by your oncologist."
    },
    {
      "turn_number": 42,
      "time": "2175-03-02 10:05:00",
      "speaker": "Patient",
      "text": "Thanks, Doctor. I’ll follow everything."
    },
    {
      "turn_number": 43,
      "time": "2175-03-02 10:06:00",
      "speaker": "Doctor",
      "text": "You’re welcome. Take care, and keep up the good work."
    }
  ],
  "summary": {
    "admission_start": "2175-02-27 19:09:00",
    "admission_end": "2175-03-02 15:23:00",
    "summary_paragraph": "Mr. ___ was admitted after an unwitnessed fall while intoxicated, presenting with chest pain. Imaging revealed six left-sided rib fractures and a small, stable left apical pneumothorax that resolved without intervention. He experienced transient confusion that resolved with supportive care. On hospital day two, he developed abdominal distension and vomiting; a KUB showed gastric distention, prompting NG tube placement, which was removed the following day after improvement. His pain was managed with a transition from PCA morphine to oral oxycodone. His multiple myeloma was stable, though his platelet count was low, leading to temporary discontinuation of warfarin. He was discharged to a sub-acute rehabilitation facility with instructions for pain management, incentive spirometry, and follow-up with his oncology team.",
    "problems": [
      "Closed fracture of multiple ribs, unspecified",
      "Traumatic pneumothorax without mention of open wound into thorax",
      "Multiple myeloma, without mention of having achieved remission",
      "Peripheral stem cells replaced by transplant",
      "Polyneuropathy in diabetes",
      "Chronic viral hepatitis B without mention of hepatic coma without mention of hepatitis delta",
      "Unspecified fall",
      "Alcohol abuse, unspecified",
      "Esophageal reflux",
      "Obstructive sleep apnea (adult)(pediatric)",
      "Unspecified essential hypertension",
      "Sickle-cell trait",
      "Pure hypercholesterolemia",
      "Diabetes with neurological manifestations, type II or unspecified type, not stated as uncontrolled",
      "Long-term (current) use of insulin",
      "Personal history of malignant neoplasm of prostate",
      "Personal history of pulmonary embolism",
      "Personal history of malignant neoplasm of bladder",
      "Acquired absence of organ, genital organs"
    ]
  }
}
